mkitem!{mktrait!{# [doc = " An iterator that reports an accurate length using size_hint."] # [doc = ""] # [doc = " The iterator reports a size hint where it is either exact"] # [doc = " (lower bound is equal to upper bound), or the upper bound is [`None`]."] # [doc = " The upper bound must only be [`None`] if the actual iterator length is"] # [doc = " larger than [`usize::MAX`]. In that case, the lower bound must be"] # [doc = " [`usize::MAX`], resulting in an [`Iterator::size_hint()`] of"] # [doc = " `(usize::MAX, None)`."] # [doc = ""] # [doc = " The iterator must produce exactly the number of elements it reported"] # [doc = " or diverge before reaching the end."] # [doc = ""] # [doc = " # When *shouldn't* an adapter be `TrustedLen`?"] # [doc = ""] # [doc = " If an adapter makes an iterator *shorter* by a given amount, then it's"] # [doc = " usually incorrect for that adapter to implement `TrustedLen`.  The inner"] # [doc = " iterator might return more than `usize::MAX` items, but there's no way to"] # [doc = " know what `k` elements less than that will be, since the `size_hint` from"] # [doc = " the inner iterator has already saturated and lost that information."] # [doc = ""] # [doc = " This is why [`Skip<I>`](crate::iter::Skip) isn't `TrustedLen`, even when"] # [doc = " `I` implements `TrustedLen`."] # [doc = ""] # [doc = " # Safety"] # [doc = ""] # [doc = " This trait must only be implemented when the contract is upheld. Consumers"] # [doc = " of this trait must inspect [`Iterator::size_hint()`]’s upper bound."] # [unstable (feature = "trusted_len" , issue = "37572")] # [rustc_unsafe_specialization_marker] pub unsafe trait TrustedLen : Iterator { }}}
mkitem!{mkimpl!{# [unstable (feature = "trusted_len" , issue = "37572")] unsafe impl < I : TrustedLen + ? Sized > TrustedLen for & mut I { }}}
mkitem!{mktrait!{# [doc = " An iterator that when yielding an item will have taken at least one element"] # [doc = " from its underlying [`SourceIter`]."] # [doc = ""] # [doc = " Calling any method that advances the iterator, e.g.  [`next()`] or [`try_fold()`],"] # [doc = " guarantees that for each step at least one value of the iterator's underlying source"] # [doc = " has been moved out and the result of the iterator chain could be inserted"] # [doc = " in its place, assuming structural constraints of the source allow such an insertion."] # [doc = " In other words this trait indicates that an iterator pipeline can be collected in place."] # [doc = ""] # [doc = " The primary use of this trait is in-place iteration. Refer to the [`vec::in_place_collect`]"] # [doc = " module documentation for more information."] # [doc = ""] # [doc = " [`vec::in_place_collect`]: ../../../../alloc/vec/in_place_collect/index.html"] # [doc = " [`SourceIter`]: crate::iter::SourceIter"] # [doc = " [`next()`]: Iterator::next"] # [doc = " [`try_fold()`]: Iterator::try_fold"] # [unstable (issue = "none" , feature = "inplace_iteration")] # [doc (hidden)] # [rustc_specialization_trait] pub unsafe trait InPlaceIterable { # [doc = " The product of one-to-many item expansions that happen throughout the iterator pipeline."] # [doc = " E.g. [[u8; 4]; 4].iter().flatten().flatten() would have a `EXPAND_BY` of 16."] # [doc = " This is an upper bound, i.e. the transformations will produce at most this many items per"] # [doc = " input. It's meant for layout calculations."] const EXPAND_BY : Option < NonZero < usize > > ; # [doc = " The product of many-to-one item reductions that happen throughout the iterator pipeline."] # [doc = " E.g. [u8].iter().array_chunks::<4>().array_chunks::<4>() would have a `MERGE_BY` of 16."] # [doc = " This is a lower bound, i.e. the transformations will consume at least this many items per"] # [doc = " output."] const MERGE_BY : Option < NonZero < usize > > ; }}}
mkitem!{mktrait!{# [doc = " A type that upholds all invariants of [`Step`]."] # [doc = ""] # [doc = " The invariants of [`Step::steps_between()`] are a superset of the invariants"] # [doc = " of [`TrustedLen`]. As such, [`TrustedLen`] is implemented for all range"] # [doc = " types with the same generic type argument."] # [doc = ""] # [doc = " # Safety"] # [doc = ""] # [doc = " The implementation of [`Step`] for the given type must guarantee all"] # [doc = " invariants of all methods are upheld. See the [`Step`] trait's documentation"] # [doc = " for details. Consumers are free to rely on the invariants in unsafe code."] # [unstable (feature = "trusted_step" , issue = "85731")] # [rustc_specialization_trait] pub unsafe trait TrustedStep : Step + Copy { }}}